import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Bases de datos — Modeladas y afinadas","description":"PostgreSQL, MySQL, MongoDB, Redis, Firebase — diseño de esquemas, afinado de consultas y trade-offs honestos.","frontmatter":{"title":"Bases de datos — Modeladas y afinadas","description":"PostgreSQL, MySQL, MongoDB, Redis, Firebase — diseño de esquemas, afinado de consultas y trade-offs honestos."},"headers":[],"relativePath":"es/skills/databases/index.md","filePath":"es/skills/databases/index.md"}`),a={name:`es/skills/databases/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="bases-de-datos-—-modeladas-y-afinadas" tabindex="-1">Bases de datos — Modeladas y afinadas <a class="header-anchor" href="#bases-de-datos-—-modeladas-y-afinadas" aria-label="Permalink to “Bases de datos — Modeladas y afinadas”">​</a></h1><p>La mayoría de los problemas de rendimiento que encuentro son problemas de base de datos disfrazados de frontend. Diseño esquemas con intención, mido antes de optimizar, y elijo motores por carga de trabajo, no por moda.</p><h2 id="elecciones-de-motor-que-realmente-hago" tabindex="-1">Elecciones de motor que realmente hago <a class="header-anchor" href="#elecciones-de-motor-que-realmente-hago" aria-label="Permalink to “Elecciones de motor que realmente hago”">​</a></h2><table tabindex="0"><thead><tr><th>Motor</th><th>Cuándo lo elijo</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>OLTP por defecto: paneles, APIs, todo lo que tiene relaciones y restricciones.</td></tr><tr><td>MySQL / MariaDB</td><td>Realidades de hosting compartido y stacks heredados.</td></tr><tr><td>MongoDB</td><td>Datos documentales de evolución rápida — bóvedas de sesión, logs.</td></tr><tr><td>Redis</td><td>Caché, colas, rate limiting, estado de sesión.</td></tr><tr><td>Firebase / Supabase</td><td>Productos sin operaciones y prototipos que aún necesitan auth + datos.</td></tr></tbody></table><ul><li><strong>Diseño de esquemas</strong> — normalización donde importa la integridad, desnormalización deliberada donde dominan las lecturas.</li><li><strong>Afinado de consultas</strong> — planes EXPLAIN, estrategia de índices, cacería de N+1.</li><li><strong>Migraciones</strong> — versionadas, reversibles, ensayadas en staging.</li><li><strong>Backups</strong> — automatizados, probados y realmente restaurables (el único tipo que cuenta).</li></ul>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};